// src/components/ui/RepaymentModal.js
import React, { useState, useEffect } from 'react';
import { repaymentsAPI, loansAPI } from '../../services/api';
import { X, CheckCircle } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('en-US').format(n || 0) + ' FCFA';

export default function RepaymentModal({ loanId, scheduleId, onClose, onSave }) {
  const [loans, setLoans] = useState([]);
  const [selectedLoanId, setSelectedLoanId] = useState(loanId || '');
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!loanId) {
      setLoading(true);
      loansAPI.getAll().then(r => {
        setLoans(r.data.data.filter(l => l.status !== 'COMPLETED'));
        setLoading(false);
      }).catch(() => setLoading(false));
    }
  }, [loanId]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedLoanId || !amount) return;
    setSubmitting(true);
    setError('');
    try {
      await repaymentsAPI.record({
        loanId: selectedLoanId,
        scheduleId: scheduleId || undefined,
        amount: parseFloat(amount),
        note,
      });
      onSave();
    } catch (err) {
      setError(err.response?.data?.message || 'Error during saving');
    }
    setSubmitting(false);
  };

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 450 }}>
        <div className="modal-header">
          <h3><CheckCircle size={18} style={{ verticalAlign: 'middle', marginRight: 8, color: 'var(--accent)' }} /> Record a payment</h3>
          <button onClick={onClose} className="btn btn-icon btn-outline">✕</button>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            {error && <div className="alert alert-danger">{error}</div>}

            <div className="form-group">
              <label>Target Loan *</label>
              <select 
                className="form-control" 
                value={selectedLoanId} 
                onChange={e => setSelectedLoanId(e.target.value)}
                required
                disabled={!!loanId || loading}
              >
                <option value="">-- Select a loan --</option>
                {loans.map(l => (
                  <option key={l._id} value={l._id}>
                    {l.clientId?.name} — {fmtMoney(l.amount)} ({l.status})
                  </option>
                ))}
              </select>
              {loading && <p style={{ fontSize: 11, color: 'var(--gray-400)', marginTop: 4 }}>Loading loans...</p>}
            </div>

            <div className="form-group">
              <label>Amount (FCFA) *</label>
              <input 
                className="form-control" 
                type="number" 
                value={amount} 
                onChange={e => setAmount(e.target.value)} 
                placeholder="Ex: 5000"
                required 
              />
            </div>

            <div className="form-group" style={{ marginBottom: 0 }}>
              <label>Note (optional)</label>
              <textarea 
                className="form-control" 
                value={note} 
                onChange={e => setNote(e.target.value)} 
                placeholder="Payment comment..."
                rows={2}
              />
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" onClick={onClose} className="btn btn-outline">Cancel</button>
            <button type="submit" className="btn btn-accent" disabled={submitting || (loading && !loanId)}>
              {submitting ? 'Saving...' : 'Confirm Payment'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
